const fs = require("fs");
const file = "/w/node_modules/agents/dist/chat/index.js";
const pkg = JSON.parse(fs.readFileSync("/w/node_modules/agents/package.json", "utf8"));
(async () => {
  let m;
  try {
    m = await import(file);
  } catch (e) {
    console.error("ERROR: cannot import agents/chat: " + e.message);
    process.exit(2);
  }
  const resolve = m.resolveChatRecoveryConfig;
  if (typeof resolve !== "function") {
    console.error("ERROR: resolveChatRecoveryConfig is not exported");
    process.exit(2);
  }
  const off = resolve(false);
  const on = resolve(true);
  if (!off || typeof off !== "object" || typeof on.maxAttempts !== "number") {
    console.error("ERROR: unexpected resolved config " + JSON.stringify(off));
    process.exit(2);
  }
  if (off.enabled === false) {
    console.error("FAIL: agents " + pkg.version + " chatRecovery false resolves to enabled: false, so durable recovery is disabled");
    process.exit(1);
  }
  if (JSON.stringify(off) === JSON.stringify(on) && !("enabled" in off)) {
    console.log("OK: agents " + pkg.version + " chatRecovery false resolves to the default recovery configuration " + JSON.stringify(off));
    process.exit(0);
  }
  console.error("ERROR: unexpected configs false=" + JSON.stringify(off) + " true=" + JSON.stringify(on));
  process.exit(2);
})();

